int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    if (n < 2) { puts("0"); return 0; }
    int answer = 0;
    // The first deletion fixes the common sum: only three candidates exist.
    for (long long target : {a[0] + a[1], a[n - 2] + a[n - 1], a[0] + a[n - 1]}) {
        // previous[left] = most operations on the interval of the previous length starting at left.
        vector<int> previous(n + 2, 0), current(n + 2, 0);
