import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = (long) st.nval; }
        if (n < 2) { System.out.println(0); return; }
        int answer = 0;
        // The first deletion fixes the common sum: only three candidates exist.
        for (long target : new long[] {a[0] + a[1], a[n - 2] + a[n - 1], a[0] + a[n - 1]}) {
            // previous[left] = most operations on the interval of the previous length starting at left.
            int[] previous = new int[n + 2], current = new int[n + 2];
            for (int length = 2 + n % 2; length <= n; length += 2) {
                Arrays.fill(current, 0);
                for (int left = 0; left + length <= n; left++) {
                    int right = left + length - 1, best = 0;
                    if (a[left] + a[left + 1] == target) best = Math.max(best, 1 + previous[left + 2]);
                    if (a[right - 1] + a[right] == target) best = Math.max(best, 1 + previous[left]);
                    if (a[left] + a[right] == target) best = Math.max(best, 1 + previous[left + 1]);
                    current[left] = best;
                }
                int[] t = previous; previous = current; current = t;
            }
            answer = Math.max(answer, previous[0]);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	if n < 2 {
		fmt.Println(0)
		return
	}
	answer := 0
	// The first deletion fixes the common sum: only three candidates exist.
	for _, target := range []int{a[0] + a[1], a[n-2] + a[n-1], a[0] + a[n-1]} {
		// previous[left] = most operations on the interval of the previous length starting at left.
		previous := make([]int, n+2)
		current := make([]int, n+2)
		for length := 2 + n%2; length <= n; length += 2 {
			clear(current)
			for left := 0; left+length <= n; left++ {
				right, best := left+length-1, 0
				if a[left]+a[left+1] == target {
					best = max(best, 1+previous[left+2])
				}
				if a[right-1]+a[right] == target {
					best = max(best, 1+previous[left])
				}
				if a[left]+a[right] == target {
					best = max(best, 1+previous[left+1])
				}
				current[left] = best
			}
			previous, current = current, previous
		}
		answer = max(answer, previous[0])
	}
	fmt.Println(answer)
}
